// JobActionsResourceV4.java:275
PATCH /job/{jobId}/context/{contextId}/actions/{actionId}/fix

// Request: List<{ documentId, pageId, number, currentText, replacementText }>
// Flow:
// 1. Skip no-op if currentText == replacementText
// 2. detectionService.detect()               ← re-runs detection
// 3. textBlockIndexUpdaterService.update()   ← updates Elasticsearch
// 4. jobActionsService.fixActionText()       ← persists ActionMapping
// 5. Publishes JobItemsChangeEvent + JobActionsChangeEvent

// 'Check' (PRD/FE) == ActionMapping (backend) — see REPO-CONTEXT.md
// Underlying text unit:
TextBlock {
  id, jobId, documentId, pageId, pageNumber,
  number,       // position/sequence
  text,         // TEXT column — ONE full sentence string
  locations,    // Set<Location> — pixel bounding boxes
  actionMappings // Set<ActionMapping> — linked checks
}
// TextBlockDTO.words: List<Word> EXISTS in OCR output
// — but is NEVER persisted. Discarded after OCR processing.
